const seed={tracks:[{id:'kp',name:'Kart Point',city:'Brasília - DF',layouts:[{id:'curto',name:'Traçado Curto',distance:'650m'},{id:'longo',name:'Traçado Longo',distance:'950m'}]}],events:[{id:'e1',name:'Barrigudos',track:'kp',layout:'curto',date:'2026-08-20'}],batteries:[{id:'b1',name:'Série A',event:'e1',surface:'seca',date:'2026-08-20'}],records:[]};
let db=JSON.parse(localStorage.kartstats||'null')||seed,page='dashboard',modal=null,editing=null,sort='best',filters={track:'',layout:'',event:'',surface:''},imported=[];
const $=s=>document.querySelector(s),save=()=>localStorage.kartstats=JSON.stringify(db),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>{let m=Math.floor(n/60),s=(n%60).toFixed(3).padStart(6,'0');return `${String(m).padStart(2,'0')}:${s}`},parse=v=>{let m=String(v).match(/(\d+):?(\d{2})[.,]?(\d{3})?/);return m?Number(m[1])*60+Number(m[2])+Number(m[3]||0)/1000:NaN};
function go(p){page=p;render()}function cls(t){return t<=46.5?'green':t<=47.6?'yellow':'red'}function status(c){return c==='green'?'🔥 RÁPIDO':c==='yellow'?'⚡ MEDIANO':'🐌 LENTO'}
function nav(){return `<aside class="side"><div class="brand"><b>▦</b> KartStats<small>TELEMETRIA</small></div><div class="navtitle">ANÁLISE</div><div class="nav"><button class="${page==='dashboard'?'active':''}" onclick="go('dashboard')">📊 Dashboard</button><button class="${page==='ranking'?'active':''}" onclick="go('ranking')">🏁 Ranking de Karts</button><div class="navtitle">GESTÃO</div><button onclick="go('tracks')">🏟️ Kartódromos</button><button onclick="go('events')">🏆 Eventos</button><button onclick="go('batteries')">📋 Baterias</button><button onclick="go('entry')">⏱️ Registrar Tempo</button></div></aside>`}
function recs(){return db.records.filter(r=>{let b=db.batteries.find(x=>x.id===r.battery),e=db.events.find(x=>x.id===b?.event);return(!filters.event||e?.id===filters.event)&&(!filters.surface||b?.surface===filters.surface)&&(!filters.track||e?.track===filters.track)&&(!filters.layout||e?.layout===filters.layout)})}
function agg(){let m={};recs().forEach(r=>{m[r.kart]??={kart:r.kart,best:r.best,count:0,bats:new Set()};m[r.kart].best=Math.min(m[r.kart].best,r.best);m[r.kart].count++;m[r.kart].bats.add(r.battery)});return Object.values(m).map(x=>({...x,bats:x.bats.size})).sort((a,b)=>sort==='kart'?a.kart-b.kart:a.best-b.best)}
function dashboard(){let rs=agg(),ref=rs[0]?.best||0;return `<div class="actions"><div><h2>Dashboard</h2><p>Visão geral dos karts</p></div><button class="btn" onclick="go('entry')">+ Registrar Tempo</button></div><div class="stats"><div class="stat green">RÁPIDOS 🔥<b>${rs.filter(x=>cls(x.best)==='green').length}</b><small>abaixo da referência</small></div><div class="stat yellow">MEDIANOS ⚡<b>${rs.filter(x=>cls(x.best)==='yellow').length}</b><small>faixa intermediária</small></div><div class="stat red">LENTOS 🐌<b>${rs.filter(x=>cls(x.best)==='red').length}</b><small>acima da referência</small></div><div class="stat purple">REFERÊNCIA ⭐<b>${ref?fmt(ref):'—'}</b><small>melhor volta do filtro</small></div></div><div class="filters">${filter('Kartódromo','track',db.tracks.map(t=>[t.id,t.name]))}${filter('Traçado','layout',db.tracks.flatMap(t=>t.layouts).map(l=>[l.id,l.name]))}${filter('Evento','event',db.events.map(e=>[e.id,e.name]))}${filter('Pista','surface',[['seca','Seca'],['molhada','Molhada']])}<div class="field"><label>Ordenar</label><select onchange="sort=this.value;render()"><option value="best">Melhor Volta</option><option value="kart">Número do Kart</option></select></div></div><div class="legend"><span class="purple">⭐ Melhor tempo</span> <span class="green">🔥 Rápido</span> <span class="yellow">⚡ Mediano</span> <span class="red">🐌 Lento</span></div><div class="card tablewrap"><table class="table"><thead><tr><th>POS.</th><th>KART</th><th>MELHOR VOLTA</th><th>BATERIAS</th><th>REGISTROS</th><th>STATUS</th></tr></thead><tbody>${rs.map((r,i)=>{let c=r.best===ref?'purple':cls(r.best);return `<tr><td>${i+1}</td><td><span class="kart ${c}">${r.kart}</span></td><td class="${c}"><b>${fmt(r.best)} ${r.best===ref?'⭐':''}</b></td><td>${r.bats}</td><td>${r.count}</td><td class="status ${c}">${r.best===ref?'⭐ MELHOR':status(c)}</td></tr>`}).join('')}</tbody></table></div>`}
function filter(label,key,opts){return `<div class="field"><label>${label}</label><select onchange="filters.${key}=this.value;render()"><option value="">Todos${label==='Pista'?'as':''} ${label.toLowerCase()}</option>${opts.map(x=>`<option value="${x[0]}" ${filters[key]===x[0]?'selected':''}>${esc(x[1])}</option>`).join('')}</select></div>`}
function ranking(){return `<div class="actions"><h2>Ranking de Karts</h2></div><div class="grid">${agg().map((r,i)=>`<div class="kartcard ${cls(r.best)}"><div class="row"><span>#${i+1}</span><span class="kart">${r.kart}</span><b>${status(cls(r.best))}</b></div><p class="muted">MELHOR VOLTA</p><div class="time">${fmt(r.best)}</div><small>${r.bats} bateria(s) · ${r.count} registro(s)</small></div>`).join('')}</div>`}
function tracks(){return `<div class="actions"><div><h2>Kartódromos & Traçados</h2><p>Gerencie locais e traçados</p></div><button class="btn" onclick="editing=null;modal='track';render()">+ Novo Kartódromo</button></div><div class="list">${db.tracks.map(t=>`<div class="card"><div class="row"><div><h3>${esc(t.name)}</h3><div class="meta">📍 ${esc(t.city)} · ${t.layouts.length} traçado(s)</div></div><button class="iconbtn" onclick="editing='${t.id}';modal='track';render()">✎ Editar</button></div>${t.layouts.map(l=>`<div class="listitem"><b>🏁 ${esc(l.name)}</b><span class="meta">${esc(l.distance)}</span></div>`).join('')}</div>`).join('')}</div>`}
function events(){return `<div class="actions"><div><h2>Eventos & Campeonatos</h2><p>Vincule baterias aos locais</p></div><button class="btn" onclick="editing=null;modal='event';render()">+ Novo Evento</button></div><div class="grid">${db.events.map(e=>`<div class="kartcard"><div class="row"><h3>${esc(e.name)}</h3><button class="iconbtn" onclick="editing='${e.id}';modal='event';render()">✎</button></div><div class="meta">🏟️ ${db.tracks.find(t=>t.id===e.track)?.name||''}<br>📅 ${e.date}</div></div>`).join('')}</div>`}
function batteries(){return `<div class="actions"><div><h2>Gerenciar Baterias</h2><p>Consulte os pilotos registrados em cada sessão</p></div><button class="btn" onclick="editing=null;modal='battery';render()">+ Nova Bateria</button></div><div class="list">${db.batteries.map(b=>{let rs=db.records.filter(r=>r.battery===b.id),e=db.events.find(x=>x.id===b.event);return `<details class="card"><summary class="row"><span><b>${esc(b.name)}</b><span class="meta">📅 ${b.date} · 🏆 ${esc(e?.name||'')} · ${b.surface.toUpperCase()} · ${rs.length} registros</span></span><button class="iconbtn" onclick="event.preventDefault();editing='${b.id}';modal='battery';render()">✎</button></summary><table class="table"><tbody>${rs.map(r=>`<tr><td>${r.kart}</td><td>${esc(r.pilot)}</td><td>${fmt(r.best)}</td></tr>`).join('')||'<tr><td>Nenhum piloto registrado.</td></tr>'}</tbody></table></details>`}).join('')}</div>`}
function entry(){return `<div class="actions"><h2>Registrar Tempo</h2></div><div class="card"><h3>⚡ Entrada Rápida</h3><div class="filters"><div class="field"><label>Bateria</label><select id="battery">${db.batteries.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Kart</label><input id="kart" inputmode="numeric"></div><div class="field"><label>Piloto</label><input id="pilot"></div><div class="field"><label>Melhor volta</label><input id="time" placeholder="00:46.118"></div></div><button class="btn" onclick="add()">✓ Registrar</button></div><div class="card"><h3>📄 Importar PDF / Excel</h3><label class="drop"><input type="file" accept=".pdf,.csv,.xlsx,.xls,.txt" onchange="pick(this)"><b>Toque aqui para selecionar o arquivo</b>PDF, CSV ou Excel</label><div id="importmsg"></div>${imported.length?`<div class="field" style="margin-top:12px"><label>Bateria de destino</label><select id="importBattery"><option value="">Selecione...</option>${db.batteries.map(b=>`<option value="${b.id}">${esc(b.name)} — ${esc(db.events.find(e=>e.id===b.event)?.name||'')}</option>`).join('')}</select></div><div class="card"><h3>Relação importada</h3><table class="table"><tbody>${imported.map(x=>`<tr><td>${x.kart}</td><td>${esc(x.pilot)}</td><td>${fmt(x.best)}</td><td class="${x.registered?'green':'yellow'}">${x.registered?'REGISTRADO':'AGUARDANDO'}</td></tr>`).join('')}</tbody></table><button class="btn" onclick="registerImport()">Registrar resultados na bateria</button></div>`:''}</div>`}
function add(){let t=parse($('#time').value),k=Number($('#kart').value);if(!k||isNaN(t))return alert('Informe kart e tempo válidos.');db.records.push({id:Date.now(),battery:$('#battery').value,kart:k,pilot:$('#pilot').value,best:t});save();render()}
function pick(i){let f=i.files[0];if(!f)return;imported=db.records.slice(0,5).map(r=>({...r,registered:false}));render();$('#importmsg').innerHTML=`Arquivo selecionado: <b>${esc(f.name)}</b><br><button class="btn" onclick="registerImport()">Preparar registro</button>`}
function registerImport(){let b=$('#importBattery')?.value;if(!b)return alert('Selecione a bateria de destino.');imported.forEach(x=>db.records.push({...x,id:Date.now()+Math.random(),battery:b,registered:undefined}));imported=imported.map(x=>({...x,registered:true}));save();render()}
function saveModal(){let id=editing||Date.now().toString(),name=$('#mname').value;if(modal==='track'){let x=db.tracks.find(t=>t.id===editing);if(x){x.name=name;x.city=$('#mcity').value}else db.tracks.push({id,name,city:$('#mcity').value,layouts:[]})}if(modal==='event'){let x=db.events.find(e=>e.id===editing),v={id,name,track:$('#mtrack').value,layout:'',date:$('#mdate').value};if(x)Object.assign(x,v);else db.events.push(v)}if(modal==='battery'){let x=db.batteries.find(b=>b.id===editing),v={id,name,event:$('#mevent').value,surface:$('#msurface').value,date:new Date().toISOString().slice(0,10)};if(x)Object.assign(x,v);else db.batteries.push(v)}save();modal=null;editing=null;render()}
function modalView(){if(!modal)return '';let x={};if(editing)x=modal==='track'?db.tracks.find(t=>t.id===editing)||{}:modal==='event'?db.events.find(e=>e.id===editing)||{}:db.batteries.find(b=>b.id===editing)||{};return `<div class="modal"><div class="modalbox"><h3>${editing?'Editar':'Novo'} ${modal==='track'?'Kartódromo':modal==='event'?'Evento':'Bateria'}</h3><div class="modalgrid"><div class="field"><label>Nome</label><input id="mname" value="${esc(x.name)}"></div>${modal==='track'?'<div class="field"><label>Cidade</label><input id="mcity" value="'+esc(x.city||'')+'"></div>':modal==='event'?'<div class="field"><label>Data</label><input id="mdate" type="date" value="'+(x.date||'')+'"></div><div class="field"><label>Kartódromo</label><select id="mtrack">'+db.tracks.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')+'</select></div>':'<div class="field"><label>Evento</label><select id="mevent">'+db.events.map(e=>`<option value="${e.id}">${e.name}</option>`).join('')+'</select></div><div class="field"><label>Pista</label><select id="msurface"><option value="seca">Seca</option><option value="molhada">Molhada</option></select></div>'}</div><button class="btn" onclick="saveModal()">Salvar</button><button class="btn ghost" onclick="modal=null;render()">Cancelar</button></div></div>`}
function render(){let [h,p]=({dashboard:['Dashboard','Visão geral dos karts'],ranking:['Ranking de Karts','Análise detalhada'],tracks:['Kartódromos','Locais e traçados'],events:['Eventos','Campeonatos'],batteries:['Baterias','Sessões e registros'],entry:['Registrar Tempo','Entrada de dados']}[page]);$('#app').innerHTML=`${nav()}<main class="main"><header class="top"><div><h1>${h}</h1><p>${p}</p></div></header><section class="content">${page==='dashboard'?dashboard():page==='ranking'?ranking():page==='tracks'?tracks():page==='events'?events():page==='batteries'?batteries():entry()}</section></main>${modalView()}`};render();
/* V3.1 corrections */
function dashboard(){let rs=agg(),ref=rs[0]?.best||0,ts=filters.track?db.tracks.filter(t=>t.id===filters.track):db.tracks,es=db.events.filter(e=>(!filters.track||e.track===filters.track)&&(!filters.layout||e.layout===filters.layout));return `<div class="actions"><div><h2>Dashboard</h2><p>Visão geral dos karts</p></div><button class="btn" onclick="go('entry')">+ Registrar Tempo</button></div><div class="filters"><div class="field"><label>Kartódromo</label><select onchange="filters.track=this.value;filters.layout='';filters.event='';render()"><option value="">Todos</option>${db.tracks.map(t=>`<option value="${t.id}" ${filters.track===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Traçado</label><select onchange="filters.layout=this.value;filters.event='';render()"><option value="">Todos</option>${ts.flatMap(t=>t.layouts).map(l=>`<option value="${l.id}" ${filters.layout===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Evento</label><select onchange="filters.event=this.value;render()"><option value="">Todos</option>${es.map(e=>`<option value="${e.id}" ${filters.event===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Pista</label><select onchange="filters.surface=this.value;render()"><option value="">Todas</option><option value="seca">Seca</option><option value="molhada">Molhada</option></select></div><div class="field"><label>Ordenar</label><select onchange="sort=this.value;render()"><option value="best">Melhor Volta</option><option value="kart">Número do Kart</option></select></div></div><div class="card tablewrap"><table class="table"><thead><tr><th>POS.</th><th>KART</th><th>MELHOR VOLTA</th><th>BATERIAS</th><th>REGISTROS</th><th>STATUS</th></tr></thead><tbody>${rs.map((r,i)=>{let c=r.best===ref?'purple':cls(r.best);return `<tr><td>${i+1}</td><td><span class="kart ${c}">${r.kart}</span></td><td class="${c}"><b>${fmt(r.best)} ${r.best===ref?'⭐':''}</b></td><td>${r.bats}</td><td>${r.count}</td><td class="${c}">${r.best===ref?'⭐ MELHOR':status(c)}</td></tr>`}).join('')}</tbody></table></div>`}
function batteries(){return `<div class="actions"><div><h2>Gerenciar Baterias</h2><p>Consulte e edite os pilotos registrados</p></div><button class="btn" onclick="editing=null;modal='battery';render()">+ Nova Bateria</button></div><div class="list">${db.batteries.map(b=>{let rs=db.records.filter(r=>r.battery===b.id),e=db.events.find(x=>x.id===b.event);return `<details class="card" open><summary class="row"><span><b>${esc(b.name)}</b><span class="meta">📅 ${b.date} · 🏆 ${esc(e?.name||'')} · ${b.surface.toUpperCase()} · ${rs.length} registros</span></span><button class="iconbtn" onclick="event.preventDefault();editing='${b.id}';modal='battery';render()">✎</button></summary><table class="table"><thead><tr><th>KART</th><th>PILOTO</th><th>MELHOR VOLTA</th><th>AÇÕES</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.kart}</td><td>${esc(r.pilot)}</td><td>${fmt(r.best)}</td><td><button class="iconbtn" onclick="editPilot(${r.id})">✎</button><button class="iconbtn danger" onclick="deletePilot(${r.id})">×</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhum piloto registrado.</td></tr>'}</tbody></table></details>`}).join('')}</div>`}
function editPilot(id){let r=db.records.find(x=>x.id==id);if(!r)return;let p=prompt('Nome do piloto:',r.pilot);if(p===null)return;let t=prompt('Melhor volta (mm:ss.mmm):',fmt(r.best));if(t===null)return;let n=parse(t);if(!isNaN(n)){r.pilot=p;r.best=n;save();render()}}
function deletePilot(id){if(confirm('Excluir este piloto e seu tempo?')){db.records=db.records.filter(r=>r.id!=id);save();render()}}
async function pick(i){let f=i.files[0];if(!f)return;imported=[];$('#importmsg').textContent='Lendo PDF real...';try{if(f.name.toLowerCase().endsWith('.pdf')){pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise,text='';for(let p=1;p<=pdf.numPages;p++){let pg=await pdf.getPage(p),tc=await pg.getTextContent(),lines={};tc.items.forEach(it=>{let y=Math.round(it.transform[5]);(lines[y]??=[]).push(it.str)});Object.keys(lines).sort((a,b)=>b-a).forEach(y=>text+=lines[y].join(' ')+'\n');}for(let line of text.split('\n')){let m=line.match(/^\s*\d+\s+(\d+)\s+(.+?)\s+\d+\s+(\d{2}:\d{2}[.,]\d{3})\s+/);if(m)imported.push({kart:+m[1],pilot:m[2].trim(),best:parse(m[3]),registered:false})}}else{let text=await f.text();for(let line of text.split('\n')){let m=line.match(/^(\d+)[,;\t]+(.+?)[,;\t]+(\d{2}:\d{2}[.,]\d{3})/);if(m)imported.push({kart:+m[1],pilot:m[2],best:parse(m[3]),registered:false})}}render();$('#importmsg').innerHTML=`Arquivo selecionado: <b>${esc(f.name)}</b><br><span class="green">${imported.length} resultados encontrados.</span><br><button class="btn" onclick="registerImport()">Registrar resultados na bateria</button>`}catch(e){$('#importmsg').textContent='Erro ao ler o arquivo: '+e.message}}
render();
/* V7.5 — filtro de evento no ranking de pilotos, encadeado às baterias. */
let pilotEventFilter='';
const pilotRankingWithEventFilter=pilotRanking;
pilotRanking=function(){let batteries=db.batteries.filter(b=>{let e=db.events.find(x=>x.id===b.event);return !pilotEventFilter||e?.id===pilotEventFilter}),allowed=new Set(batteries.map(b=>b.id)),source=db.records.filter(r=>allowed.has(r.battery)&&(!pilotBatteryFilter||r.battery===pilotBatteryFilter)),m={};source.forEach(r=>{if(!m[r.pilot]||r.best<m[r.pilot].best)m[r.pilot]={pilot:r.pilot,best:r.best,battery:r.battery,kart:r.kart}});let rows=Object.values(m).sort((a,b)=>a.best-b.best),eventOptions=db.events.filter(e=>db.batteries.some(b=>b.event===e.id));return `<div class="actions"><div><h2>Ranking de Pilotos</h2><p>Compare os pilotos da bateria selecionada</p></div></div><div class="filters ranking-pilot-filters"><div class="field"><label>Evento</label><select onchange="pilotEventFilter=this.value;pilotBatteryFilter='';render()"><option value="">Todos os eventos</option>${eventOptions.map(e=>`<option value="${e.id}" ${pilotEventFilter===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Bateria para comparar</label><select onchange="pilotBatteryFilter=this.value;render()"><option value="">Todas as baterias${pilotEventFilter?' deste evento':''}</option>${batteries.map(b=>{let e=db.events.find(x=>x.id===b.event);return `<option value="${b.id}" ${pilotBatteryFilter===b.id?'selected':''}>${esc(e?.name||'Sem evento')} — ${esc(b.name)} (${b.date})</option>`}).join('')}</select></div></div><div class="card tablewrap"><table class="table pilot-ranking-table"><thead><tr><th>POS.</th><th>PILOTO</th><th>MELHOR VOLTA</th><th>BATERIA</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><b>${esc(r.pilot||'Não informado')}</b><small class="meta">#${r.kart}</small></td><td class="${i===0?'purple':cls(r.best)}"><b>${fmt(r.best)} ${i===0?'⭐':''}</b></td><td>${esc(db.batteries.find(b=>b.id===r.battery)?.name||'—')}</td></tr>`).join('')||'<tr><td colspan="4">Nenhum registro nessa seleção.</td></tr>'}</tbody></table></div>`};
render();
function dashboard(){let rs=agg(),ref=rs[0]?.best||0;return `<div class="actions"><div><h2>Dashboard</h2><p>Visão geral dos karts</p></div><button class="btn" onclick="go('entry')">+ Registrar Tempo</button></div><div class="stats"><div class="stat green">RÁPIDOS 🔥<b>${rs.filter(x=>cls(x.best)==='green').length}</b><small>karts abaixo da referência</small></div><div class="stat yellow">MEDIANOS ⚡<b>${rs.filter(x=>cls(x.best)==='yellow').length}</b><small>faixa intermediária</small></div><div class="stat red">LENTOS 🐌<b>${rs.filter(x=>cls(x.best)==='red').length}</b><small>karts acima da referência</small></div><div class="stat purple">MELHOR VOLTA ⭐<b>${ref?fmt(ref):'—'}</b><small>referência atual</small></div></div><div class="filters">${filter('Kartódromo','track',db.tracks.map(t=>[t.id,t.name]))}${filter('Traçado','layout',db.tracks.flatMap(t=>t.layouts).map(l=>[l.id,l.name]))}${filter('Evento','event',db.events.map(e=>[e.id,e.name]))}${filter('Pista','surface',[['seca','Seca'],['molhada','Molhada']])}<div class="field"><label>Ordenar</label><select onchange="sort=this.value;render()"><option value="best">Melhor Volta</option><option value="kart">Número do Kart</option></select></div></div><div class="card tablewrap"><table class="table"><thead><tr><th>POS.</th><th>KART</th><th>MELHOR VOLTA</th><th>BATERIAS</th><th>REGISTROS</th><th>STATUS</th></tr></thead><tbody>${rs.map((r,i)=>{let c=r.best===ref?'purple':cls(r.best);return `<tr><td>${i+1}</td><td><span class="kart ${c}">${r.kart}</span></td><td class="${c}"><b>${fmt(r.best)} ${r.best===ref?'⭐':''}</b></td><td>${r.bats}</td><td>${r.count}</td><td class="${c}">${r.best===ref?'⭐ MELHOR':status(c)}</td></tr>`}).join('')}</tbody></table></div>`}
function tracks(){return `<div class="actions"><div><h2>Kartódromos & Traçados</h2><p>Gerencie locais e traçados</p></div><button class="btn" onclick="editing=null;modal='track';render()">+ Novo Kartódromo</button></div><div class="list">${db.tracks.map(t=>`<div class="card"><div class="row"><div><h3>${esc(t.name)}</h3><div class="meta">📍 ${esc(t.city)} · ${t.layouts.length} traçado(s)</div></div><button class="iconbtn" onclick="editing='${t.id}';modal='track';render()">✎ Editar</button></div>${t.layouts.map(l=>`<div class="listitem"><div><b>🏁 ${esc(l.name)}</b><div class="meta">📏 ${esc(l.distance)}</div></div><span><button class="iconbtn" onclick="editLayout('${t.id}','${l.id}')">✎</button><button class="iconbtn danger" onclick="deleteLayout('${t.id}','${l.id}')">×</button></span></div>`).join('')}</div>`).join('')}</div>`}
function editLayout(tid,lid){let t=db.tracks.find(x=>x.id===tid),l=t.layouts.find(x=>x.id===lid),n=prompt('Nome do traçado:',l.name);if(n===null)return;let d=prompt('Distância:',l.distance);if(d===null)return;l.name=n;l.distance=d;save();render()}
function deleteLayout(tid,lid){if(confirm('Excluir este traçado?')){let t=db.tracks.find(x=>x.id===tid);t.layouts=t.layouts.filter(l=>l.id!==lid);save();render()}}
function editPilot(id){let r=db.records.find(x=>x.id==id);if(!r)return;let k=prompt('Número do kart:',r.kart);if(k===null)return;let p=prompt('Nome do piloto:',r.pilot);if(p===null)return;let t=prompt('Melhor volta (mm:ss.mmm):',fmt(r.best));if(t===null)return;let n=parse(t);if(!isNaN(n)){r.kart=Number(k);r.pilot=p;r.best=n;save();render()}}
async function pick(i){let f=i.files[0];if(!f)return;imported=[];$('#importmsg').textContent='Analisando o arquivo...';try{if(f.name.toLowerCase().endsWith('.pdf')){pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise,text='';for(let p=1;p<=pdf.numPages;p++){let pg=await pdf.getPage(p),tc=await pg.getTextContent(),lines={};tc.items.forEach(it=>{let y=Math.round(it.transform[5]);(lines[y]??=[]).push(it.str)});Object.keys(lines).sort((a,b)=>b-a).forEach(y=>text+=lines[y].join(' ')+'\n')}for(let line of text.split('\n')){let m=line.match(/^\s*\d+\s+(\d+)\s+(.+?)\s+\d+\s+(\d{2}:\d{2}[.,]\d{3})\s+/);if(m)imported.push({kart:+m[1],pilot:m[2].trim(),best:parse(m[3]),registered:false})}}else{let text=await f.text();for(let line of text.split('\n')){let m=line.match(/^(\d+)[,;\t]+(.+?)[,;\t]+(\d{2}:\d{2}[.,]\d{3})/);if(m)imported.push({kart:+m[1],pilot:m[2],best:parse(m[3]),registered:false})}}render();$('#importmsg').innerHTML=imported.length?`Arquivo selecionado: <b>${esc(f.name)}</b><br><span class="green">${imported.length} resultados encontrados.</span>`:`Arquivo selecionado: <b>${esc(f.name)}</b><br><span class="yellow">Este PDF não possui texto selecionável. Ele precisa de OCR para ser lido.</span>`}catch(e){$('#importmsg').textContent='Erro ao ler o arquivo: '+e.message}}
