function nav(){return `<aside class="side" id="sidebar"><div class="brand"><b>▦</b> KartStats<small>TELEMETRIA</small></div><div class="navtitle">ANÁLISE</div><div class="nav"><button onclick="go('dashboard')">📊 Dashboard</button><button onclick="go('ranking')">🏁 Ranking de Karts</button><div class="navtitle">GESTÃO</div><button onclick="go('tracks')">🏟️ Kartódromos</button><button onclick="go('events')">🏆 Eventos</button><button onclick="go('batteries')">📋 Baterias</button><button onclick="go('entry')">⏱️ Registrar Tempo</button></div></aside>`}
function timeMask(i){let v=i.value.replace(/\D/g,'').slice(0,7);if(v.length<=2)i.value=v;else if(v.length<=5)i.value=`00:${v.slice(0,-3).padStart(2,'0')}.${v.slice(-3)}`;else i.value=`${v.slice(0,-5).padStart(2,'0')}:${v.slice(-5,-3)}.${v.slice(-3)}`}
function entry(){return `<div class="actions"><h2>Registrar Tempo</h2></div><div class="card"><h3>⚡ Entrada Rápida</h3><div class="filters"><div class="field"><label>Bateria</label><select id="battery">${db.batteries.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Kart</label><input id="kart" inputmode="numeric"></div><div class="field"><label>Piloto</label><input id="pilot"></div><div class="field"><label>Melhor volta (mm:ss.mmm)</label><input id="time" inputmode="numeric" placeholder="00:46.503" oninput="timeMask(this)"></div></div><button class="btn" onclick="add()">✓ Registrar</button></div><div class="card"><h3>📄 Importar PDF / Excel</h3><label class="drop"><input type="file" accept=".pdf,.csv,.xlsx,.xls,.txt" onchange="pick(this)"><b>Toque aqui para selecionar o arquivo</b>PDF, CSV ou Excel</label><div id="importmsg"></div>${imported.length?`<div class="field" style="margin-top:12px"><label>Bateria de destino</label><select id="importBattery"><option value="">Selecione...</option>${db.batteries.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="card"><h3>Relação importada</h3><table class="table"><tbody>${imported.map(x=>`<tr><td>${x.kart}</td><td>${esc(x.pilot)}</td><td>${fmt(x.best)}</td><td>${x.registered?'REGISTRADO':'AGUARDANDO'}</td></tr>`).join('')}</tbody></table><button class="btn" onclick="registerImport()">Registrar resultados na bateria</button></div>`:''}</div>`}
function editLayout(tid,lid){let t=db.tracks.find(x=>x.id===tid),l=t.layouts.find(x=>x.id===lid);let n=prompt('Nome do traçado:',l.name);if(n===null)return;let d=prompt('Distância do traçado:',l.distance||'');if(d===null)return;l.name=n;l.distance=d;save();render()}
function render(){let [h,p]=({dashboard:['Dashboard','Visão geral dos karts'],ranking:['Ranking de Karts','Análise detalhada'],tracks:['Kartódromos','Locais e traçados'],events:['Eventos','Campeonatos'],batteries:['Baterias','Sessões e registros'],entry:['Registrar Tempo','Entrada de dados']}[page]);$('#app').innerHTML=`${nav()}<main class="main"><header class="top"><button class="menu-toggle" onclick="document.querySelector('#sidebar').classList.toggle('open')">☰</button><div><h1>${h}</h1><p>${p}</p></div></header><section class="content">${page==='dashboard'?dashboard():page==='ranking'?ranking():page==='tracks'?tracks():page==='events'?events():page==='batteries'?batteries():entry()}</section></main>${modalView()}`}
