async function pick(i){let f=i.files[0];if(!f)return;imported=[];$('#importmsg').textContent='Lendo PDF...';try{let pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise,text='';for(let p=1;p<=pdf.numPages;p++){let pg=await pdf.getPage(p),tc=await pg.getTextContent();if(tc.items.length){text+=tc.items.map(x=>x.str).join(' ')+'\n'}else{let vp=pg.getViewport({scale:2}),c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await pg.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;$('#importmsg').textContent='PDF escaneado: executando OCR...';let o=await Tesseract.recognize(c,'por+eng');text+=o.data.text+'\n'}}let re=/^\s*\d+\s+(\d+)\s+(.+?)\s+\d+\s+(\d{2}:\d{2}[.,]\d{3})\s+/gm,m;while((m=re.exec(text)))imported.push({kart:+m[1],pilot:m[2].trim(),best:parse(m[3]),registered:false});render();$('#importmsg').innerHTML=imported.length?`Arquivo: <b>${esc(f.name)}</b><br><span class="green">${imported.length} resultados encontrados por leitura/OCR.</span>`:`Arquivo: <b>${esc(f.name)}</b><br><span class="yellow">Não foi possível identificar linhas de resultado.</span>`}catch(e){$('#importmsg').textContent='Erro ao ler PDF: '+e.message}}
render();
function filter(label,key,opts){let first=label==='Pista'?'Todas as pistas':'Todos';return `<div class="field"><label>${label}</label><select onchange="filters.${key}=this.value;render()"><option value="">${first}</option>${opts.map(x=>`<option value="${x[0]}" ${filters[key]===x[0]?'selected':''}>${esc(x[1])}</option>`).join('')}</select></div>`}
async function pick(i){let f=i.files[0];if(!f)return;imported=[];$('#importmsg').textContent='Lendo PDF e preparando OCR...';try{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer()}).promise,text='';for(let p=1;p<=pdf.numPages;p++){let pg=await pdf.getPage(p),tc=await pg.getTextContent();let native=tc.items.map(x=>x.str).join(' ');if(native.trim().length>80)text+=native+'\n';let vp=pg.getViewport({scale:2.5}),c=document.createElement('canvas');c.width=vp.width;c.height=vp.height;await pg.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;if(!native.trim()||native.length<200){if(!window.Tesseract)throw Error('OCR não carregou. Verifique sua conexão e tente novamente.');let o=await Tesseract.recognize(c,'eng',{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@5/tesseract-core.wasm.js',logger:m=>{if(m.status==='recognizing text')$('#importmsg').textContent=`OCR: ${Math.round((m.progress||0)*100)}%`}});text+=o.data.text+'\n'}}let re=/^\s*(?:\d+|NC)\s+(\d+)\s+(.+?)\s+\d+\s+(\d{2}:\d{2}[.,]\d{3})\s+/gm,m;while((m=re.exec(text))){let n=parse(m[3]);if(!isNaN(n))imported.push({kart:+m[1],pilot:m[2].trim(),best:n,registered:false})}render();$('#importmsg').innerHTML=imported.length?`Arquivo: <b>${esc(f.name)}</b><br><span class="green">${imported.length} resultados encontrados.</span>`:`Arquivo: <b>${esc(f.name)}</b><br><span class="yellow">Não foram identificadas linhas de resultado.</span>`}catch(e){$('#importmsg').textContent='Erro no OCR/PDF: '+e.message}}
render();
function dashboard(){let rs=agg(),ref=rs[0]?.best||0;return `<div class="actions"><div><h2>Dashboard</h2><p>Visão geral dos karts</p></div><button class="btn" onclick="go('entry')">+ Registrar Tempo</button></div><div class="stats"><div class="stat green">RÁPIDOS 🔥<b>${rs.filter(x=>cls(x.best)==='green').length}</b><small>karts rápidos</small></div><div class="stat yellow">MEDIANOS ⚡<b>${rs.filter(x=>cls(x.best)==='yellow').length}</b><small>faixa intermediária</small></div><div class="stat red">LENTOS 🐌<b>${rs.filter(x=>cls(x.best)==='red').length}</b><small>karts lentos</small></div><div class="stat purple">REFERÊNCIA ⭐<b>${ref?fmt(ref):'—'}</b><small>melhor volta</small></div></div><div class="filters">${filter('Kartódromo','track',db.tracks.map(t=>[t.id,t.name]))}${filter('Traçado','layout',db.tracks.filter(t=>!filters.track||t.id===filters.track).flatMap(t=>t.layouts).map(l=>[l.id,l.name]))}${filter('Evento','event',db.events.filter(e=>(!filters.track||e.track===filters.track)&&(!filters.layout||e.layout===filters.layout)).map(e=>[e.id,e.name]))}${filter('Pista','surface',[['seca','Seca'],['molhada','Molhada']])}<div class="field"><label>Ordenar</label><select onchange="sort=this.value;render()"><option value="best" ${sort==='best'?'selected':''}>Melhor Volta</option><option value="kart" ${sort==='kart'?'selected':''}>Número do Kart</option></select></div></div><div class="card tablewrap"><table class="table"><thead><tr><th>POS.</th><th>KART</th><th>MELHOR VOLTA</th><th>BATERIAS</th><th>REGISTROS</th><th>STATUS</th></tr></thead><tbody>${rs.map((r,i)=>{let c=r.best===ref?'purple':cls(r.best);return `<tr><td>${i+1}</td><td><span class="kart ${c}">${r.kart}</span></td><td class="${c}"><b>${fmt(r.best)} ${r.best===ref?'⭐':''}</b></td><td>${r.bats}</td><td>${r.count}</td><td class="${c}">${r.best===ref?'⭐ MELHOR':status(c)}</td></tr>`}).join('')}</tbody></table></div>`}
function tracks(){return `<div class="actions"><div><h2>Kartódromos & Traçados</h2><p>Gerencie locais e traçados</p></div><button class="btn" onclick="editing=null;modal='track';render()">+ Novo Kartódromo</button></div><div class="list">${db.tracks.map(t=>`<div class="card"><div class="row"><div><h3>${esc(t.name)}</h3><div class="meta">📍 ${esc(t.city)} · ${t.layouts.length} traçado(s)</div></div><button class="iconbtn" onclick="editing='${t.id}';modal='track';render()">✎ Editar</button></div>${t.layouts.map(l=>`<div class="listitem"><div><b>🏁 ${esc(l.name)}</b><div class="meta">📏 ${esc(l.distance||'')}</div></div><span><button class="iconbtn" onclick="editLayout('${t.id}','${l.id}')">✎ Editar</button><button class="iconbtn danger" onclick="deleteLayout('${t.id}','${l.id}')">× Excluir</button></span></div>`).join('')}</div>`).join('')}</div>`}
function modalView(){if(!modal)return '';let x=editing?(modal==='track'?db.tracks.find(t=>t.id===editing):modal==='event'?db.events.find(e=>e.id===editing):db.batteries.find(b=>b.id===editing))||{}:{};if(modal==='track')return `<div class="modal"><div class="modalbox"><h3>${editing?'Editar':'Novo'} Kartódromo</h3><div class="modalgrid"><div class="field"><label>Nome</label><input id="mname" value="${esc(x.name)}"></div><div class="field"><label>Cidade</label><input id="mcity" value="${esc(x.city)}"></div><div class="field"><label>Novo traçado</label><input id="mlayout" placeholder="Nome do traçado"></div><div class="field"><label>Distância</label><input id="mdistance" placeholder="650m"></div></div><button class="btn" onclick="saveModal()">Salvar</button><button class="btn ghost" onclick="modal=null;render()">Cancelar</button></div></div>`;return `<div class="modal"><div class="modalbox"><h3>${editing?'Editar':'Novo'} ${modal==='event'?'Evento':'Bateria'}</h3><div class="field"><label>Nome</label><input id="mname" value="${esc(x.name)}"></div>${modal==='event'?'<div class="field"><label>Data</label><input id="mdate" type="date" value="'+(x.date||'')+'"></div><div class="field"><label>Kartódromo</label><select id="mtrack">'+db.tracks.map(t=>`<option value="${t.id}">${t.name}</option>`).join('')+'</select></div>':'<div class="field"><label>Evento</label><select id="mevent">'+db.events.map(e=>`<option value="${e.id}">${e.name}</option>`).join('')+'</select></div><div class="field"><label>Pista</label><select id="msurface"><option value="seca">Seca</option><option value="molhada">Molhada</option></select></div>'}<button class="btn" onclick="saveModal()">Salvar</button><button class="btn ghost" onclick="modal=null;render()">Cancelar</button></div></div>`}
function saveModal(){let id=editing||Date.now().toString();if(modal==='track'){let t=editing?db.tracks.find(x=>x.id===editing):null;if(t){t.name=$('#mname').value;t.city=$('#mcity').value;if($('#mlayout').value)t.layouts.push({id:'l'+Date.now(),name:$('#mlayout').value,distance:$('#mdistance').value})}else db.tracks.push({id,name:$('#mname').value,city:$('#mcity').value,layouts:$('#mlayout').value?[{id:'l'+Date.now(),name:$('#mlayout').value,distance:$('#mdistance').value}]:[]})}else if(modal==='event'){let e=editing?db.events.find(x=>x.id===editing):null,v={id,name:$('#mname').value,track:$('#mtrack').value,layout:db.tracks.find(t=>t.id===$('#mtrack').value)?.layouts[0]?.id||'',date:$('#mdate').value};if(e)Object.assign(e,v);else db.events.push(v)}else{let b=editing?db.batteries.find(x=>x.id===editing):null,v={id,name:$('#mname').value,event:$('#mevent').value,surface:$('#msurface').value,date:new Date().toISOString().slice(0,10)};if(b)Object.assign(b,v);else db.batteries.push(v)}save();modal=null;editing=null;render()}
function editPilot(id){let r=db.records.find(x=>x.id==id);if(!r)return;let k=prompt('Número do kart:',String(r.kart));if(k===null)return;let p=prompt('Nome do piloto:',r.pilot||'');if(p===null)return;let t=prompt('Melhor volta:',fmt(r.best));if(t===null)return;let n=parse(t);if(isNaN(n))return alert('Use o formato 00:46.503');r.kart=Number(k);r.pilot=p;r.best=n;save();render()}
render();
function normalizeHeader(v){return String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'')}
function sheetTime(v){if(typeof v==='number')return v<1?v*86400:v;let s=String(v||'').trim();if(/^\d{1,2}:\d{2}[.,]\d{3}$/.test(s))return parse(s);if(/^\d{1,2}:\d{2}:\d{2}/.test(s)){let a=s.split(':');return Number(a[0])*3600+Number(a[1])*60+Number(a[2].replace(',','.'))}return parse(s)}
async function pick(i){let f=i.files[0];if(!f)return;imported=[];$('#importmsg').textContent='Lendo planilha...';try{let buf=await f.arrayBuffer(),wb=XLSX.read(buf,{type:'array',cellDates:true}),rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:''});if(!rows.length)throw Error('A planilha está vazia.');let heads=rows[0].map(normalizeHeader),find=(names)=>{let idx=heads.findIndex(h=>names.some(n=>h.includes(n)));return idx<0?null:idx};let ik=find(['kart','numero','competidor','carro']),ip=find(['piloto','nome','driver']),it=find(['melhorvolta','tmv','bestlap','tempo','volta']);if(ik===null)ik=0;if(ip===null)ip=1;if(it===null)it=2;let start=(ik===0&&ip===1&&it===2&&heads.every(h=>!h))?0:1;for(let row of rows.slice(start)){let kart=Number(String(row[ik]||'').replace(/\D/g,'')),pilot=String(row[ip]||'').trim(),best=sheetTime(row[it]);if(kart&&pilot&&Number.isFinite(best))imported.push({kart,pilot,best,registered:false})}if(!imported.length)throw Error('Não encontrei linhas com kart, piloto e melhor volta.');render();$('#importmsg').innerHTML=`Arquivo: <b>${esc(f.name)}</b><br><span class="green">${imported.length} resultados encontrados na planilha.</span><br><small>Confira a relação abaixo e selecione a bateria.</small>`}catch(e){$('#importmsg').innerHTML=`<span class="yellow">Não foi possível ler a planilha: ${esc(e.message)}</span>`}}
render();
function formatTimeOnBlur(i){let v=i.value.replace(/\D/g,'').slice(0,7);if(v.length>=5)i.value=`${v.slice(0,-5).padStart(2,'0')}:${v.slice(-5,-3)}.${v.slice(-3)}`;else if(v)i.value=v}
function entry(){return `<div class="actions"><h2>Registrar Tempo</h2></div><div class="card"><h3>⚡ Entrada Rápida</h3><div class="filters"><div class="field"><label>Bateria</label><select id="battery">${db.batteries.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Kart</label><input id="kart" inputmode="numeric"></div><div class="field"><label>Piloto</label><input id="pilot"></div><div class="field"><label>Melhor volta (mm:ss.mmm)</label><input id="time" inputmode="numeric" placeholder="Digite os números" oninput="this.value=this.value.replace(/\\D/g,'').slice(0,7)" onblur="formatTimeOnBlur(this)"></div></div><button class="btn" onclick="add()">✓ Registrar</button></div><div class="card"><h3>📄 Importar PDF / Excel</h3><label class="drop"><input type="file" accept=".pdf,.csv,.xlsx,.xls,.txt" onchange="pick(this)"><b>Toque aqui para selecionar o arquivo</b>PDF, CSV ou Excel</label><div id="importmsg"></div>${imported.length?`<div class="field" style="margin-top:12px"><label>Bateria de destino</label><select id="importBattery"><option value="">Selecione...</option>${db.batteries.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="card"><h3>Relação importada</h3><table class="table"><tbody>${imported.map(x=>`<tr><td>${x.kart}</td><td>${esc(x.pilot)}</td><td>${fmt(x.best)}</td><td>${x.registered?'REGISTRADO':'AGUARDANDO'}</td></tr>`).join('')}</tbody></table><button class="btn" onclick="registerImport()">Registrar resultados na bateria</button></div>`:''}</div>`}
function deletePilot(id){if(confirm('Excluir este piloto?')){db.records=db.records.filter(r=>r.id!=id);save();render()}}
function deleteBattery(id){if(confirm('Excluir esta bateria e todos os seus pilotos?')){db.records=db.records.filter(r=>r.battery!==id);db.batteries=db.batteries.filter(b=>b.id!==id);save();render()}}
function deleteEvent(id){if(confirm('Excluir este evento e suas baterias?')){let bs=db.batteries.filter(b=>b.event===id).map(b=>b.id);db.records=db.records.filter(r=>!bs.includes(r.battery));db.batteries=db.batteries.filter(b=>b.event!==id);db.events=db.events.filter(e=>e.id!==id);save();render()}}
function batteries(){return `<div class="actions"><div><h2>Gerenciar Baterias</h2><p>Consulte e edite os pilotos registrados</p></div><button class="btn" onclick="editing=null;modal='battery';render()">+ Nova Bateria</button></div><div class="list">${db.batteries.map(b=>{let rs=db.records.filter(r=>r.battery===b.id),e=db.events.find(x=>x.id===b.event);return `<details class="card" open><summary class="row"><span><b>${esc(b.name)}</b><span class="meta">📅 ${b.date} · 🏆 ${esc(e?.name||'')} · ${b.surface.toUpperCase()} · ${rs.length} registros</span></span><span><button class="iconbtn" onclick="event.preventDefault();editing='${b.id}';modal='battery';render()">✎</button><button class="iconbtn danger" onclick="event.preventDefault();deleteBattery('${b.id}')">×</button></span></summary><table class="table"><thead><tr><th>KART</th><th>PILOTO</th><th>MELHOR VOLTA</th><th>AÇÕES</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.kart}</td><td>${esc(r.pilot)}</td><td>${fmt(r.best)}</td><td><button class="iconbtn" onclick="editPilot(${r.id})">✎</button><button class="iconbtn danger" onclick="deletePilot(${r.id})">×</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhum piloto registrado.</td></tr>'}</tbody></table></details>`}).join('')}</div>`}
function events(){return `<div class="actions"><div><h2>Eventos & Campeonatos</h2><p>Vincule baterias aos locais</p></div><button class="btn" onclick="editing=null;modal='event';render()">+ Novo Evento</button></div><div class="grid">${db.events.map(e=>`<div class="kartcard"><div class="row"><h3>${esc(e.name)}</h3><span><button class="iconbtn" onclick="editing='${e.id}';modal='event';render()">✎</button><button class="iconbtn danger" onclick="deleteEvent('${e.id}')">×</button></span></div><div class="meta">🏟️ ${db.tracks.find(t=>t.id===e.track)?.name||''}<br>📅 ${e.date}</div></div>`).join('')}</div>`}
render();
function agg(){let m={};recs().forEach(r=>{m[r.kart]??={kart:r.kart,best:r.best,total:0,count:0,bats:new Set()};m[r.kart].best=Math.min(m[r.kart].best,r.best);m[r.kart].total+=r.best;m[r.kart].count++;m[r.kart].bats.add(r.battery)});return Object.values(m).map(x=>({...x,avg:x.total/x.count,bats:x.bats.size})).sort((a,b)=>sort==='kart'?a.kart-b.kart:a.best-b.best)}
function dashboard(){let rs=agg(),ref=rs[0]?.best||0;return `<div class="actions"><div><h2>Dashboard</h2><p>Visão geral dos karts</p></div><button class="btn" onclick="go('entry')">+ Registrar Tempo</button></div><div class="stats"><div class="stat green">RÁPIDOS 🔥<b>${rs.filter(x=>cls(x.best)==='green').length}</b><small>karts rápidos</small></div><div class="stat yellow">MEDIANOS ⚡<b>${rs.filter(x=>cls(x.best)==='yellow').length}</b><small>faixa intermediária</small></div><div class="stat red">LENTOS 🐌<b>${rs.filter(x=>cls(x.best)==='red').length}</b><small>karts lentos</small></div><div class="stat purple">REFERÊNCIA ⭐<b>${ref?fmt(ref):'—'}</b><small>melhor volta</small></div></div><div class="filters">${filter('Kartódromo','track',db.tracks.map(t=>[t.id,t.name]))}${filter('Traçado','layout',db.tracks.filter(t=>!filters.track||t.id===filters.track).flatMap(t=>t.layouts).map(l=>[l.id,l.name]))}${filter('Evento','event',db.events.filter(e=>(!filters.track||e.track===filters.track)&&(!filters.layout||e.layout===filters.layout)).map(e=>[e.id,e.name]))}${filter('Pista','surface',[['seca','Seca'],['molhada','Molhada']])}<div class="field"><label>Ordenar</label><select onchange="sort=this.value;render()"><option value="best" ${sort==='best'?'selected':''}>Melhor Volta</option><option value="kart" ${sort==='kart'?'selected':''}>Número do Kart</option></select></div></div><div class="card tablewrap"><table class="table"><thead><tr><th>POS.</th><th>KART</th><th>MELHOR VOLTA</th><th>MÉDIA DAS MELHORES VOLTAS</th><th>BATERIAS</th><th>REGISTROS</th><th>STATUS</th></tr></thead><tbody>${rs.map((r,i)=>{let c=r.best===ref?'purple':cls(r.best);return `<tr><td>${i+1}</td><td><span class="kart ${c}">${r.kart}</span></td><td class="${c}"><b>${fmt(r.best)} ${r.best===ref?'⭐':''}</b></td><td><b>${fmt(r.avg)}</b></td><td>${r.bats}</td><td>${r.count}</td><td class="${c}">${r.best===ref?'⭐ MELHOR':status(c)}</td></tr>`}).join('')}</tbody></table></div>`}
render();
/* Ordenação adicional por média */
const renderWithAverageSort=render;
render=function(){renderWithAverageSort();let s=document.querySelector('.filters select:last-child');if(s&&!s.querySelector('option[value="avg"]')){let o=document.createElement('option');o.value='avg';o.textContent='Média das melhores voltas';s.appendChild(o)}if(s)s.value=sort};
function agg(){let m={};recs().forEach(r=>{m[r.kart]??={kart:r.kart,best:r.best,total:0,count:0,bats:new Set()};m[r.kart].best=Math.min(m[r.kart].best,r.best);m[r.kart].total+=r.best;m[r.kart].count++;m[r.kart].bats.add(r.battery)});return Object.values(m).map(x=>({...x,avg:x.total/x.count,bats:x.bats.size})).sort((a,b)=>sort==='kart'?a.kart-b.kart:sort==='avg'?a.avg-b.avg:a.best-b.best)}
render();
