function loginScreen(){return `<main style="min-height:100vh;display:grid;place-items:center;padding:20px;background:#07090d"><div class="modalbox" style="width:min(420px,100%);text-align:center"><img src="assets/kartstats-logo.png" alt="KartStats" style="width:64px;height:64px;object-fit:contain"><h2>KartStats Telemetria</h2><p class="muted">Entre para acessar seus campeonatos</p><div class="field" style="text-align:left"><label>E-mail</label><input id="loginEmail" type="email" placeholder="voce@email.com"></div><div class="field" style="text-align:left"><label>Senha</label><input id="loginPass" type="password" placeholder="Sua senha"></div><button class="btn" style="width:100%;margin-top:12px" onclick="doLogin()">Entrar</button><button class="btn ghost" style="width:100%;margin-top:8px" onclick="showSignup()">Criar minha conta</button><button class="btn ghost" style="width:100%;margin-top:8px" onclick="showForgot()">Esqueci minha senha</button><p id="loginMsg" class="meta"></p></div></main>`}
