function resetScreen(){return `<main style="min-height:100vh;display:grid;place-items:center;padding:20px;background:#07090d"><div class="modalbox" style="width:min(420px,100%);text-align:center"><img src="assets/kartstats-logo.png" alt="KartStats" style="width:64px;height:64px;object-fit:contain"><h2>Nova senha</h2><div class="field" style="text-align:left"><label>Nova senha</label><input id="newPass" type="password"></div><div class="field" style="text-align:left"><label>Confirmar senha</label><input id="newPass2" type="password"></div><button class="btn" style="width:100%;margin-top:12px" onclick="updatePassword()">Salvar nova senha</button><p id="resetMsg" class="meta"></p></div></main>`}
async function updatePassword(){let a=$('#newPass').value,b=$('#newPass2').value;if(a.length<6)return authMessage('#resetMsg','A senha precisa ter pelo menos 6 caracteres.');if(a!==b)return authMessage('#resetMsg','As senhas não são iguais.');let {error}=await supabaseClient.auth.updateUser({password:a});if(error)return authMessage('#resetMsg',error.message);authMessage('#resetMsg','Senha alterada com sucesso!',true);setTimeout(()=>{history.replaceState({},'',window.location.pathname);render()},1000)}
const renderRecovery=render;
render=function(){if(location.hash.includes('type=recovery')){document.querySelector('#app').innerHTML=resetScreen();return}renderRecovery()};
render();
function agg(){let m={};recs().forEach(r=>{m[r.kart]??={kart:r.kart,best:r.best,total:0,count:0,bats:new Set(),pilot:r.pilot,battery:r.battery};m[r.kart].total+=r.best;m[r.kart].count++;m[r.kart].bats.add(r.battery);if(r.best<m[r.kart].best){m[r.kart].best=r.best;m[r.kart].pilot=r.pilot;m[r.kart].battery=r.battery}});return Object.values(m).map(x=>({...x,avg:x.total/x.count,bats:x.bats.size})).sort((a,b)=>sort==='kart'?a.kart-b.kart:sort==='avg'?a.avg-b.avg:a.best-b.best)}
function showPilot(kart,pilot,time,battery){let old=document.querySelector('.pilot-pop');if(old)old.remove();let box=document.createElement('div');box.className='pilot-pop';box.innerHTML=`<b>🏎️ Piloto da melhor volta</b><strong>${esc(pilot||'Não informado')}</strong><small>Kart ${esc(kart)} · ${fmt(time)}<br>Bateria: ${esc(db.batteries.find(b=>b.id===battery)?.name||'—')}</small>`;document.body.appendChild(box);setTimeout(()=>box.remove(),4500)}
const renderPilotInfo=render;
render=function(){renderPilotInfo();if(page!=='dashboard')return;let rows=agg(),cells=[...document.querySelectorAll('.table tbody tr')];rows.forEach((r,i)=>{let c=cells[i]?.children[2];if(!c)return;c.classList.add('best-time');c.title=`Piloto: ${r.pilot||'Não informado'}`;c.onclick=()=>showPilot(r.kart,r.pilot,r.best,r.battery)})};
render();
const renderPilotHover=render;
render=function(){renderPilotHover();if(page!=='dashboard')return;let rows=agg(),cells=[...document.querySelectorAll('.table tbody tr')];rows.forEach((r,i)=>{let c=cells[i]?.children[2];if(c)c.onmouseenter=()=>showPilot(r.kart,r.pilot,r.best,r.battery)})};
render();
function showPilot(kart,pilot,time,battery){let old=document.querySelector('.pilot-pop');if(old)old.remove();let b=db.batteries.find(x=>x.id===battery),e=db.events.find(x=>x.id===b?.event),t=db.tracks.find(x=>x.id===e?.track),l=t?.layouts.find(x=>x.id===e?.layout);let card=document.querySelector('.detail-card');if(!card){card=document.createElement('div');card.className='detail-card';let table=document.querySelector('.tablewrap');(table?.parentElement||document.querySelector('.content')).appendChild(card)}card.innerHTML=`<h3>🔎 Detalhamento da melhor volta</h3><div class="detail-grid"><div><span>Piloto</span><b>${esc(pilot||'Não informado')}</b></div><div><span>Kart</span><b>${esc(kart)}</b></div><div><span>Tempo</span><b>${fmt(time)}</b></div><div><span>Bateria</span><b>${esc(b?.name||'—')}</b></div><div><span>Evento</span><b>${esc(e?.name||'—')}</b></div><div><span>Kartódromo</span><b>${esc(t?.name||'—')}</b></div><div><span>Traçado</span><b>${esc(l?.name||'—')}</b></div></div>`}
render();
function pilotRanking(){let m={};db.records.forEach(r=>{if(!m[r.pilot]||r.best<m[r.pilot].best)m[r.pilot]={pilot:r.pilot,best:r.best,battery:r.battery,kart:r.kart}});let rows=Object.values(m).sort((a,b)=>a.best-b.best);return `<div class="actions"><div><h2>Ranking de Pilotos</h2><p>Classificação pela melhor volta de cada piloto cadastrado</p></div></div><div class="card tablewrap"><table class="table"><thead><tr><th>POS.</th><th>PILOTO</th><th>MELHOR VOLTA</th><th>BATERIA</th></tr></thead><tbody>${rows.map((r,i)=>{let b=db.batteries.find(x=>x.id===r.battery),c=i===0?'purple':cls(r.best);return `<tr><td>${i+1}</td><td><b>${esc(r.pilot||'Não informado')}</b><small class="meta">Kart ${r.kart}</small></td><td class="${c}"><b>${fmt(r.best)} ${i===0?'⭐':''}</b></td><td>${esc(b?.name||'—')}</td></tr>`}).join('')||'<tr><td colspan="4">Nenhum piloto cadastrado.</td></tr>'}</tbody></table></div>`}
function nav(){return `<aside class="side" id="sidebar"><div class="brand"><img src="assets/kartstats-logo.png" alt="KartStats" style="width:24px;height:24px;object-fit:contain;vertical-align:middle;margin-right:6px"> KartStats<small>TELEMETRIA</small></div><div class="navtitle">ANÁLISE</div><div class="nav"><button onclick="go('dashboard')">📊 Dashboard</button><button onclick="go('ranking')">🏁 Ranking de Pilotos</button><div class="navtitle">GESTÃO</div><button onclick="go('tracks')">🏟️ Kartódromos</button><button onclick="go('events')">🏆 Eventos</button><button onclick="go('batteries')">📋 Baterias</button><button onclick="go('entry')">⏱️ Registrar Tempo</button></div></aside>`}
