function batteries(){return `<div class="actions"><div><h2>Gerenciar Baterias</h2><p>Consulte e edite os pilotos registrados</p></div><button class="btn" onclick="editing=null;modal='battery';render()">+ Nova Bateria</button></div><div class="list">${db.batteries.map(b=>{let rs=db.records.filter(r=>r.battery===b.id),e=db.events.find(x=>x.id===b.event),t=db.tracks.find(x=>x.id===e?.track);return `<details class="card"><summary class="row"><span><strong>${esc(e?.name||'Sem evento')} — ${esc(b.name)}</strong><span class="meta">📅 ${b.date} · ${b.surface==='molhada'?'🌧️ Molhada':'☀️ Seca'} · ${rs.length} registros</span></span><span><button class="iconbtn" onclick="event.preventDefault();editing='${b.id}';modal='battery';render()">✎</button><button class="iconbtn danger" onclick="event.preventDefault();deleteBattery('${b.id}')">×</button></span></summary><div class="meta" style="margin:10px 0">🏟️ ${esc(t?.name||'Kartódromo não informado')}</div><table class="table"><thead><tr><th>KART</th><th>PILOTO</th><th>MELHOR VOLTA</th><th>AÇÕES</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.kart}</td><td>${esc(r.pilot)}</td><td>${fmt(r.best)}</td><td><button class="iconbtn" onclick="editPilot(${r.id})">✎</button><button class="iconbtn danger" onclick="deletePilot(${r.id})">×</button></td></tr>`).join('')||'<tr><td colspan="4">Nenhum piloto registrado.</td></tr>'}</tbody></table></details>`}).join('')}</div>`}
render();
let pilotBatteryFilter='';
function pilotRanking(){let source=db.records.filter(r=>!pilotBatteryFilter||r.battery===pilotBatteryFilter),m={};source.forEach(r=>{if(!m[r.pilot]||r.best<m[r.pilot].best)m[r.pilot]={pilot:r.pilot,best:r.best,battery:r.battery,kart:r.kart}});let rows=Object.values(m).sort((a,b)=>a.best-b.best);return `<div class="actions"><div><h2>Ranking de Pilotos</h2><p>Compare os pilotos da bateria selecionada</p></div></div><div class="filters" style="grid-template-columns:minmax(240px,420px)"><div class="field"><label>Bateria para comparar</label><select onchange="pilotBatteryFilter=this.value;render()"><option value="">Todas as baterias</option>${db.batteries.map(b=>{let e=db.events.find(x=>x.id===b.event);return `<option value="${b.id}" ${pilotBatteryFilter===b.id?'selected':''}>${esc(e?.name||'Sem evento')} — ${esc(b.name)} (${b.date})</option>`}).join('')}</select></div></div><div class="card tablewrap"><table class="table"><thead><tr><th>POS.</th><th>PILOTO</th><th>MELHOR VOLTA</th><th>BATERIA</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><b>${esc(r.pilot||'Não informado')}</b><small class="meta">Kart ${r.kart}</small></td><td class="${i===0?'purple':cls(r.best)}"><b>${fmt(r.best)} ${i===0?'⭐':''}</b></td><td>${esc(db.batteries.find(b=>b.id===r.battery)?.name||'—')}</td></tr>`).join('')||'<tr><td colspan="4">Nenhum registro nessa bateria.</td></tr>'}</tbody></table></div>`}
render();
function printReport(){window.print()}
function exportTable(){let table=document.querySelector('.content table');if(!table)return;let lines=[...table.rows].map(row=>[...row.cells].map(c=>`"${c.innerText.replace(/"/g,'""')}"`).join(';'));let blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=(page==='ranking'?'ranking-pilotos':'dashboard-karts')+'.csv';a.click();URL.revokeObjectURL(a.href)}
const renderExports=render;
render=function(){renderExports();if(page==='dashboard'||page==='ranking'){let a=document.querySelector('.actions');if(a&&!a.querySelector('.export-actions')){let box=document.createElement('span');box.className='export-actions';box.innerHTML='<button class="btn ghost" onclick="exportTable()">⇩ Exportar CSV</button> <button class="btn ghost" onclick="printReport()">▣ Imprimir / PDF</button>';a.appendChild(box)}}};
render();
/* V5.4 — mostrar/ocultar senha em login e cadastro, acessível por teclado e toque. */
function togglePassword(inputId,button){let field=document.getElementById(inputId);if(!field)return;let show=field.type==='password';field.type=show?'text':'password';button.textContent=show?'◉':'◎';button.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');button.setAttribute('aria-pressed',show?'true':'false');field.focus()}
function loginScreen(){return `<main class="auth-screen"><div class="modalbox auth-box"><div class="auth-brand"><img src="assets/kartstats-logo.png" alt="KartStats"><h2>KartStats Telemetria</h2><p class="muted">Entre para acessar seus campeonatos</p></div><div class="field"><label for="loginEmail">E-mail</label><input id="loginEmail" type="email" autocomplete="username" placeholder="voce@email.com"></div><div class="field"><label for="loginPass">Senha</label><div class="password-wrap"><input id="loginPass" type="password" autocomplete="current-password" placeholder="Sua senha"><button class="password-toggle" type="button" aria-label="Mostrar senha" aria-pressed="false" onclick="togglePassword('loginPass',this)">◎</button></div></div><button class="btn auth-action" onclick="doLogin()">Entrar</button><button class="btn ghost auth-action" onclick="showSignup()">Criar minha conta</button><button class="btn ghost auth-action" onclick="showForgot()">Esqueci minha senha</button><p id="loginMsg" class="meta" aria-live="polite"></p></div></main>`}
function signupScreen(){return `<main class="auth-screen"><div class="modalbox auth-box"><div class="auth-brand"><img src="assets/kartstats-logo.png" alt="KartStats"><h2>Criar conta</h2><p class="muted">Crie seu acesso online ao KartStats</p></div><div class="field"><label for="signupEmail">E-mail</label><input id="signupEmail" type="email" autocomplete="email" placeholder="voce@email.com"></div><div class="field"><label for="signupPass">Senha</label><div class="password-wrap"><input id="signupPass" type="password" autocomplete="new-password" placeholder="Mínimo de 6 caracteres"><button class="password-toggle" type="button" aria-label="Mostrar senha" aria-pressed="false" onclick="togglePassword('signupPass',this)">◎</button></div></div><div class="field"><label for="signupConfirm">Confirmar senha</label><div class="password-wrap"><input id="signupConfirm" type="password" autocomplete="new-password" placeholder="Digite novamente"><button class="password-toggle" type="button" aria-label="Mostrar senha" aria-pressed="false" onclick="togglePassword('signupConfirm',this)">◎</button></div></div><button class="btn auth-action" onclick="createOnlineAccount()">Criar conta</button><button class="btn ghost auth-action" onclick="signupMode=false;render()">Voltar para login</button><p id="signupMsg" class="meta" aria-live="polite"></p></div></main>`}
/* V5.5 — categorias S/A/B/C e média como métrica principal do dashboard. */
sort='avg';
function classifyDelta(value,reference){let d=Math.max(0,value-reference);return d<=0.300?'purple':d<=0.600?'green':d<=0.850?'yellow':'red'}
function status(c){return c==='purple'?'S · SUPER RÁPIDO':c==='green'?'A · RÁPIDO':c==='yellow'?'B · INTERMEDIÁRIO':'C · LENTO'}
function dashboard(){
  let rows=agg(),metric=sort==='best'?'best':'avg',reference=rows.length?Math.min(...rows.map(r=>r[metric])):0,vals=rows.map(r=>r[metric]);
  let mean=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:0,sd=vals.length?Math.sqrt(vals.reduce((a,v)=>a+(v-mean)**2,0)/vals.length):0,cv=mean?sd/mean*100:0,gap=vals.length?Math.max(...vals)-reference:0;
  let counts={purple:0,green:0,yellow:0,red:0};rows.forEach(r=>counts[classifyDelta(r[metric],reference)]++);
  let trackList=filters.track?db.tracks.filter(t=>t.id===filters.track):db.tracks;
  let eventList=db.events.filter(e=>(!filters.track||e.track===filters.track)&&(!filters.layout||e.layout===filters.layout));
  let metricLabel=metric==='avg'?'média das melhores voltas':'melhor volta';
  let cards=`<div class="stats category-stats"><div class="stat purple"><small>CATEGORIA S · SUPER RÁPIDO</small><b>${counts.purple}</b><small>até +0,300 s do líder</small></div><div class="stat green"><small>CATEGORIA A · RÁPIDO</small><b>${counts.green}</b><small>+0,301 a +0,600 s</small></div><div class="stat yellow"><small>CATEGORIA B · INTERMEDIÁRIO</small><b>${counts.yellow}</b><small>+0,601 a +0,850 s</small></div><div class="stat red"><small>CATEGORIA C · LENTO</small><b>${counts.red}</b><small>acima de +0,850 s</small></div></div>`;
  let metrics=`<div class="telemetry-metrics"><div class="telemetry-metric"><small>GAP TOTAL</small><b>+${gap.toFixed(3)}s</b><span>do kart líder ao último · pela ${metricLabel}</span></div><div class="telemetry-metric"><small>VARIAÇÃO DO LOTE</small><b>${cv.toFixed(2)}%</b><span>coeficiente de variação da métrica selecionada</span></div><div class="telemetry-metric"><small>REFERÊNCIA · ${metric==='avg'?'MÉDIA':'MELHOR VOLTA'}</small><b>${reference?fmt(reference):'—'}</b><span>${rows.length} karts considerados</span></div></div>`;
  let podium=[...rows].sort((a,b)=>a[metric]-b[metric]).slice(0,3);
  let topCards=`<div class="best3-strip"><div class="best3-heading"><b>Três melhores karts</b><small>ordenados pela ${metricLabel}</small></div>${podium.map((r,i)=>{let d=r[metric]-reference,c=classifyDelta(r[metric],reference);return `<div class="best3-item ${c}"><span class="best3-position">${i+1}</span><b>Kart ${esc(r.kart)}</b><strong>${fmt(r[metric])}</strong><small>${i===0?'LÍDER':`Δ +${d.toFixed(3)}s`} · ${r.count} volta(s)</small></div>`}).join('')||'<div class="muted">Sem tempos para os filtros selecionados.</div>'}</div>`;
  let visible=recs(),byKart={};visible.forEach(r=>(byKart[r.kart]??=[]).push(r));
  rows.sort((a,b)=>a[metric]-b[metric]);
  let trs=rows.map((r,i)=>{let c=classifyDelta(r[metric],reference),laps=(byKart[r.kart]||[]).slice().sort((a,b)=>a.best-b.best).slice(0,3),spread=laps.length>1?laps[laps.length-1].best-laps[0].best:0;
    let lapMarkup=laps.map((x,j)=>`<div class="toplap"><span>${j+1}.</span><b>${fmt(x.best)}</b><small>${esc(x.pilot||'Piloto não informado')} · ${esc(db.batteries.find(b=>b.id===x.battery)?.name||'Bateria')}</small></div>`).join('')||'<small class="muted">Sem voltas</small>';
    return `<tr data-category="${c}"><td>${i+1}</td><td><span class="kart ${c}">${esc(r.kart)}</span><span class="category-pill ${c}">${c==='purple'?'S':c==='green'?'A':c==='yellow'?'B':'C'}</span></td><td class="${c}"><b>${fmt(r.best)}</b></td><td class="primary-metric ${c}"><b>${fmt(r.avg)}</b><small class="delta-label">Δ +${Math.max(0,r.avg-reference).toFixed(3)}s vs líder</small></td><td class="top3-cell">${lapMarkup}<small class="variation-label">Variação das 3 melhores: +${spread.toFixed(3)}s</small></td><td class="status ${c}">${status(c)}</td></tr>`}).join('');
  return `<div class="actions"><div><h2>Dashboard</h2><p>Comparação de ritmo e consistência do lote</p></div><button class="btn" onclick="go('entry')">+ Registrar Tempo</button></div>${cards}${metrics}${topCards}<div class="filters"><div class="field"><label>Kartódromo</label><select onchange="filters.track=this.value;filters.layout='';filters.event='';render()"><option value="">Todos os kartódromos</option>${db.tracks.map(t=>`<option value="${t.id}" ${filters.track===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Traçado</label><select onchange="filters.layout=this.value;filters.event='';render()"><option value="">Todos os traçados</option>${trackList.flatMap(t=>t.layouts).map(l=>`<option value="${l.id}" ${filters.layout===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Evento</label><select onchange="filters.event=this.value;render()"><option value="">Todos os eventos</option>${eventList.map(e=>`<option value="${e.id}" ${filters.event===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Pista</label><select onchange="filters.surface=this.value;render()"><option value="">Todas as pistas</option><option value="seca" ${filters.surface==='seca'?'selected':''}>Seca</option><option value="molhada" ${filters.surface==='molhada'?'selected':''}>Molhada</option></select></div><div class="field"><label>Métrica principal</label><select onchange="sort=this.value;render()"><option value="avg" ${metric==='avg'?'selected':''}>Média das melhores voltas</option><option value="best" ${metric==='best'?'selected':''}>Melhor volta</option></select></div></div><div class="legend category-legend"><span class="purple">S · até +0,300 s</span><span class="green">A · até +0,600 s</span><span class="yellow">B · até +0,850 s</span><span class="red">C · acima de +0,850 s</span></div><div class="card tablewrap"><table class="table telemetry-table"><thead><tr><th>POS.</th><th>KART · CAT.</th><th>MELHOR VOLTA</th><th>MÉDIA DAS MELHORES VOLTAS</th><th>3 MELHORES RESULTADOS · VARIAÇÃO</th><th>CATEGORIA</th></tr></thead><tbody>${trs||'<tr><td colspan="6" class="muted">Nenhum registro encontrado nos filtros selecionados.</td></tr>'}</tbody></table></div>`
}
const renderClassSABC=render;
render=function(){renderClassSABC();if(!document.querySelector('.telemetry-table'))return;let metric=sort==='best'?'best':'avg',rows=agg().sort((a,b)=>a[metric]-b[metric]),reference=rows.length?Math.min(...rows.map(r=>r[metric])):0,trs=[...document.querySelectorAll('.telemetry-table tbody tr')],counts={purple:0,green:0,yellow:0,red:0};rows.forEach((r,i)=>{let c=classifyDelta(r[metric],reference);counts[c]++;let tr=trs[i];if(!tr)return;tr.dataset.category=c;tr.querySelectorAll('.kart,.category-pill,.status,td,.primary-metric').forEach(el=>['purple','green','yellow','red'].forEach(x=>el.classList.remove(x)));let kart=tr.querySelector('.kart'),pill=tr.querySelector('.category-pill'),metricCell=tr.querySelector('.primary-metric'),statusCell=tr.querySelector('.status');[kart,pill,metricCell,statusCell].forEach(el=>el?.classList.add(c));if(pill)pill.textContent=c==='purple'?'S':c==='green'?'A':c==='yellow'?'B':'C';if(statusCell)statusCell.textContent=status(c)});let stats=[...document.querySelectorAll('.category-stats .stat b')];['purple','green','yellow','red'].forEach((c,i)=>{if(stats[i])stats[i].textContent=counts[c]})};
