/* V5.3 — dashboard estilo telemetria: gap, variação e três melhores voltas por kart. */
function secondsLabel(n){return `${n>=0?'+':''}${Number(n||0).toFixed(3)}s`}
function dashboard(){
  let rows=agg(),metric=sort==='avg'?'avg':'best',reference=rows.length?Math.min(...rows.map(r=>r[metric])):0;
  let ordered=[...rows].sort((a,b)=>a[metric]-b[metric]),top=ordered.slice(0,3),values=rows.map(r=>r[metric]);
  let mean=values.length?values.reduce((a,b)=>a+b,0)/values.length:0,sd=values.length?Math.sqrt(values.reduce((s,v)=>s+(v-mean)**2,0)/values.length):0,cv=mean?sd/mean*100:0;
  let gap=values.length?Math.max(...values)-reference:0;
  let ts=filters.track?db.tracks.filter(t=>t.id===filters.track):db.tracks;
  let es=db.events.filter(e=>(!filters.track||e.track===filters.track)&&(!filters.layout||e.layout===filters.layout));
  let metrics=`<div class="telemetry-metrics"><div class="telemetry-metric"><small>GAP DO LÍDER</small><b>${secondsLabel(gap)}</b><span>diferença entre o mais rápido e o mais lento</span></div><div class="telemetry-metric"><small>VARIAÇÃO DO LOTE</small><b>${cv.toFixed(2)}%</b><span>coeficiente de variação dos karts filtrados</span></div><div class="telemetry-metric"><small>KARTS COM DADOS</small><b>${rows.length}</b><span>no filtro atual · métrica: ${metric==='avg'?'média das melhores':'melhor volta'}</span></div></div>`;
  let podium=`<div class="best3-strip"><div class="best3-heading"><b>🏁 Três melhores karts</b><small>Classificação por ${metric==='avg'?'média das melhores voltas':'melhor volta'} no filtro atual</small></div>${top.map((r,i)=>`<div class="best3-item"><span class="best3-position">${i+1}</span><b>Kart ${esc(r.kart)}</b><strong>${fmt(r[metric])}</strong><small>${i===0?'referência':secondsLabel(r[metric]-reference)} · ${r.count} volta(s)</small></div>`).join('')||'<div class="muted">Ainda não há tempos neste filtro.</div>'}</div>`;
  let bestCellTitle=metric==='avg'?'MÉDIA DAS MELHORES':'MELHOR VOLTA';
  let tableRows=rows.map((r,i)=>{
    let timeList=db.records.filter(x=>String(x.kart)===String(r.kart)&&recs().some(y=>y.id===x.id)).sort((a,b)=>a.best-b.best).slice(0,3);
    let gapText=r[metric]-reference,variation=timeList.length>1?timeList[timeList.length-1].best-timeList[0].best:0;
    let c=gapText===0?'purple':classifyDelta(gapText,0);
    let topHtml=timeList.map((x,j)=>`<div class="toplap"><span>${j+1}.</span><b>${fmt(x.best)}</b><small>${esc(x.pilot||'Piloto não informado')} · ${esc(db.batteries.find(b=>b.id===x.battery)?.name||'Bateria')}</small></div>`).join('')||'<small class="muted">Sem voltas</small>';
    return `<tr><td>${i+1}</td><td><span class="kart ${c}">${esc(r.kart)}</span></td><td class="${c} best-time" title="Variação ${secondsLabel(gapText)}"><b>${fmt(r.best)}</b><small class="delta-label">Δ ${secondsLabel(gapText)} vs líder</small></td><td class="${metric==='avg'?c:''}"><b>${fmt(r.avg)}</b>${metric==='avg'?`<small class="delta-label">Δ ${secondsLabel(gapText)} vs líder</small>`:''}</td><td>${r.bats}</td><td>${r.count}</td><td class="top3-cell">${topHtml}<small class="variation-label">Variação top 3: ${secondsLabel(variation)}</small></td><td class="status ${c}">${gapText===0?'⭐ MELHOR':status(c)}</td></tr>`;
  }).join('');
  return `<div class="actions"><div><h2>Dashboard</h2><p>Telemetria e comparação de karts do filtro selecionado</p></div><button class="btn" onclick="go('entry')">+ Registrar Tempo</button></div><div class="stats"><div class="stat green">RÁPIDOS 🔥<b>${rows.filter(x=>classifyDelta(x[metric],reference)==='green').length}</b><small>até +0,350s da referência</small></div><div class="stat yellow">MEDIANOS ⚡<b>${rows.filter(x=>classifyDelta(x[metric],reference)==='yellow').length}</b><small>até +0,850s da referência</small></div><div class="stat red">LENTOS 🐌<b>${rows.filter(x=>classifyDelta(x[metric],reference)==='red').length}</b><small>mais de +0,850s</small></div><div class="stat purple">REFERÊNCIA ⭐<b>${reference?fmt(reference):'—'}</b><small>${metric==='avg'?'média mais rápida':'melhor volta mais rápida'}</small></div></div>${metrics}${podium}<div class="filters"><div class="field"><label>Kartódromo</label><select onchange="filters.track=this.value;filters.layout='';filters.event='';render()"><option value="">Todos os kartódromos</option>${db.tracks.map(t=>`<option value="${t.id}" ${filters.track===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="field"><label>Traçado</label><select onchange="filters.layout=this.value;filters.event='';render()"><option value="">Todos os traçados</option>${ts.flatMap(t=>t.layouts).map(l=>`<option value="${l.id}" ${filters.layout===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Evento</label><select onchange="filters.event=this.value;render()"><option value="">Todos os eventos</option>${es.map(e=>`<option value="${e.id}" ${filters.event===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Pista</label><select onchange="filters.surface=this.value;render()"><option value="">Todas as pistas</option><option value="seca" ${filters.surface==='seca'?'selected':''}>Seca</option><option value="molhada" ${filters.surface==='molhada'?'selected':''}>Molhada</option></select></div><div class="field"><label>Ordenar</label><select onchange="sort=this.value;render()"><option value="best" ${sort==='best'?'selected':''}>Melhor Volta</option><option value="avg" ${sort==='avg'?'selected':''}>Média das melhores voltas</option></select></div></div><div class="card tablewrap"><table class="table telemetry-table"><thead><tr><th>POS.</th><th>KART</th><th>MELHOR VOLTA · Δ</th><th>${bestCellTitle}</th><th>BATERIAS</th><th>REGISTROS</th><th>3 MELHORES RESULTADOS · VARIAÇÃO</th><th>STATUS</th></tr></thead><tbody>${tableRows||'<tr><td colspan="8" class="muted">Nenhum registro encontrado para esses filtros.</td></tr>'}</tbody></table></div>`
}
/* Importa planilhas, PDF com texto/OCR e fotos/prints. Toda linha fica editável antes de gravar. */
function importTime(v){if(typeof v==='number')return v>0&&v<1?v*86400:v;let s=String(v||'').trim().replace(',', '.');let m=s.match(/^(\d{1,2}):([0-5]?\d)\.(\d{1,3})$/);if(m)return Number(m[1])*60+Number(m[2])+Number((m[3]+'000').slice(0,3))/1000;m=s.match(/^(\d{1,3})\.(\d{1,3})$/);if(m)return Number(m[1])+Number((m[2]+'000').slice(0,3))/1000;return parse(s)}
function timeTokens(text){return [...String(text).matchAll(/\b\d{1,2}:[0-5]?\d[.,]\d{1,3}\b|\b\d{2,3}[.,]\d{3}\b/g)].map(m=>({raw:m[0],index:m.index,time:importTime(m[0])})).filter(x=>Number.isFinite(x.time)&&x.time>10&&x.time<300)}
function parseResultLines(text){let out=[];for(let raw of String(text||'').split(/\r?\n/)){let line=raw.replace(/\s+/g,' ').trim();if(!line)continue;let times=timeTokens(line);if(!times.length)continue;let prefix=line.slice(0,times[0].index).replace(/[|;]/g,' ').trim();let nums=[...prefix.matchAll(/(?:^|\s)#?(\d{1,3})(?=\s|$)/g)];if(!nums.length)continue;let kartMatch=nums.length>1&&Number(nums[0][1])<=100&&Number(nums[1][1])<=120?nums[1]:nums[0];let kart=Number(kartMatch[1]);let pilot=prefix.slice((kartMatch.index||0)+kartMatch[0].length).replace(/^[\s:·-]+|[\s:·-]+$/g,'').replace(/\b(?:kart|pos(?:ição)?|piloto|driver)\b/ig,'').trim();if(!pilot&&times.length>1){let after=line.slice(times[0].index+times[0].raw.length,times[1].index).replace(/[|;]/g,' ').trim();pilot=after.replace(/^[\s:·-]+|[\s:·-]+$/g,'')}
    if(!pilot||/^(pos|kart|tempo|melhor volta|best lap|lap time)$/i.test(pilot))continue;
    out.push({kart,pilot,best:times[0].time,registered:false,review:true});}
  return out}
function parseSheetFile(file){let wb=XLSX.read(file,{type:'array',cellDates:true}),sheet=wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{header:1,defval:''});if(!rows.length)return [];let norm=x=>normalizeHeader(x),heads=rows[0].map(norm),find=patterns=>heads.findIndex(h=>patterns.some(p=>h.includes(p)));let ik=find(['kart','numero','competidor','carro']),ip=find(['piloto','nome','driver']),it=find(['melhorvolta','tmv','bestlap','tempo','volta','lap']),hasHeader=ik>=0||ip>=0||it>=0;if(ik<0)ik=0;if(ip<0)ip=1;if(it<0)it=2;let out=[];for(let row of rows.slice(hasHeader?1:0)){let kart=Number(String(row[ik]||'').replace(/\D/g,'')),pilot=String(row[ip]||'').trim(),best=importTime(row[it]);if(kart&&pilot&&Number.isFinite(best)&&best>10&&best<300)out.push({kart,pilot,best,registered:false,review:false})}return out}
async function readImportFile(file){let name=file.name.toLowerCase(),type=file.type||'';if(/\.(xlsx|xls|xlsm|ods)$/.test(name)){if(!window.XLSX)throw Error('Biblioteca de planilhas indisponível.');return parseSheetFile(await file.arrayBuffer())}
  if(/\.(csv|tsv|txt)$/.test(name)||type.startsWith('text/')){let txt=await file.text(),lines=txt.split(/\r?\n/),sep=lines[0].includes('\t')?'\t':lines[0].includes(';')?';':',';let out=[];for(let row of lines.slice(1)){let c=row.split(sep).map(x=>x.replace(/^\s*["']|["']\s*$/g,'').trim());let kart=Number((c[0]||'').replace(/\D/g,'')),pilot=c[1]||'',best=importTime(c[2]);if(kart&&pilot&&Number.isFinite(best)&&best>10&&best<300)out.push({kart,pilot,best,registered:false,review:false})}return out}
  let lines='';if(/\.pdf$/.test(name)||type==='application/pdf'){if(!window.pdfjsLib)throw Error('Leitor de PDF não carregou.');pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';let pdf=await pdfjsLib.getDocument({data:await file.arrayBuffer()}).promise;for(let p=1;p<=pdf.numPages;p++){let pg=await pdf.getPage(p),tc=await pg.getTextContent(),groups={};for(let it of tc.items){let y=Math.round(it.transform[5]);(groups[y]??=[]).push({x:it.transform[4],s:it.str})}let pageText=Object.keys(groups).sort((a,b)=>b-a).map(y=>groups[y].sort((a,b)=>a.x-b.x).map(x=>x.s).join(' ')).join('\n');if(pageText.replace(/\s/g,'').length<40){let vp=pg.getViewport({scale:2.5}),canvas=document.createElement('canvas');canvas.width=vp.width;canvas.height=vp.height;await pg.render({canvasContext:canvas.getContext('2d'),viewport:vp}).promise;if(!window.Tesseract)throw Error('O OCR não carregou; verifique a internet e tente novamente.');let o=await Tesseract.recognize(canvas,'eng',{logger:m=>{let el=$('#importmsg');if(el&&m.status==='recognizing text')el.textContent=`Lendo página ${p}/${pdf.numPages}: ${Math.round((m.progress||0)*100)}%`}});pageText=o.data.text}lines+=pageText+'\n'}return parseResultLines(lines)}
  if(type.startsWith('image/')||/\.(png|jpe?g|webp|bmp|tiff?)$/.test(name)){if(!window.Tesseract)throw Error('O OCR de imagem não carregou; verifique a internet.');let o=await Tesseract.recognize(file,'eng',{logger:m=>{let el=$('#importmsg');if(el&&m.status==='recognizing text')el.textContent=`Reconhecendo imagem: ${Math.round((m.progress||0)*100)}%`}});return parseResultLines(o.data.text)}
  throw Error('Formato não suportado. Use PDF, foto (JPG/PNG/WEBP), Excel, CSV ou TXT.')}
async function pick(input){let files=[...(input.files||[])];if(!files.length)return;imported=[];render();let msg=$('#importmsg');if(msg)msg.textContent='Analisando arquivo(s)…';for(let f of files){try{let parsed=await readImportFile(f);imported.push(...parsed.map(x=>({...x,source:f.name})));}catch(e){if(msg)msg.innerHTML+=`<div class="import-warning">${esc(f.name)}: ${esc(e.message)}</div>`}}
  render();msg=$('#importmsg');if(msg){let needs=imported.filter(x=>x.review).length;msg.innerHTML=`<div class="import-result ${imported.length?'':'import-warning'}"><b>${imported.length?`Encontrados ${imported.length} resultado(s).`:'Nenhum resultado identificado.'}</b>${needs?` <span>${needs} linha(s) extraída(s) por OCR precisam de conferência.</span>`:' Confira os dados antes de registrar.'}</div>`}if(!imported.length)console.warn('Importação não reconheceu linhas; reveja o formato/tabela.');}
function entry(){return `<div class="actions"><h2>Registrar Tempo</h2></div><div class="card"><h3>⚡ Entrada Rápida</h3><div class="filters"><div class="field"><label>Bateria</label><select id="battery">${db.batteries.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></div><div class="field"><label>Kart</label><input id="kart" inputmode="numeric"></div><div class="field"><label>Piloto</label><input id="pilot"></div><div class="field"><label>Melhor volta (mm:ss.mmm)</label><input id="time" inputmode="numeric" placeholder="Digite os números" oninput="this.value=this.value.replace(/\\D/g,'').slice(0,7)" onblur="formatTimeOnBlur(this)"></div></div><button class="btn" onclick="add()">✓ Registrar</button></div><div class="card import-card"><h3>📥 Importar resultados</h3><p class="muted">PDF, foto/print, Excel, CSV ou TXT. Para fotos e PDFs digitalizados usamos OCR; confira e corrija a prévia antes de gravar.</p><label class="drop import-drop"><input id="resultFiles" type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.bmp,.tif,.tiff,.xlsx,.xls,.xlsm,.ods,.csv,.tsv,.txt,application/pdf,image/*" multiple onchange="pick(this)"><b>Toque para escolher ou solte arquivos aqui</b><span>Você pode selecionar vários arquivos. As linhas extraídas ficam revisáveis.</span></label><div id="importmsg"></div>${imported.length?`<div class="field import-destination"><label>Bateria de destino (obrigatório)</label><select id="importBattery"><option value="">Selecione a bateria...</option>${db.batteries.map(b=>`<option value="${b.id}">${esc(db.events.find(e=>e.id===b.event)?.name||'Sem evento')} — ${esc(b.name)} · ${b.date||''}</option>`).join('')}</select></div><div class="card import-preview"><div class="row"><h3>Prévia da importação</h3><b>${imported.length} linha(s)</b></div><div class="tablewrap"><table class="table"><thead><tr><th>KART</th><th>PILOTO</th><th>MELHOR VOLTA</th><th>ARQUIVO / REVISÃO</th></tr></thead><tbody>${imported.map((x,i)=>`<tr><td><input class="import-edit" aria-label="Kart da linha ${i+1}" value="${esc(x.kart)}" onchange="imported[${i}].kart=this.value"></td><td><input class="import-edit" aria-label="Piloto da linha ${i+1}" value="${esc(x.pilot)}" onchange="imported[${i}].pilot=this.value"></td><td><input class="import-edit" aria-label="Tempo da linha ${i+1}" value="${fmt(x.best)}" onchange="imported[${i}].best=importTime(this.value)" onblur="this.value=Number.isFinite(imported[${i}].best)?fmt(imported[${i}].best):this.value"></td><td><small>${esc(x.source||'')}</small>${x.review?'<span class="import-review">Conferir OCR</span>':''}<button class="iconbtn danger" onclick="imported.splice(${i},1);render()" aria-label="Remover linha">×</button></td></tr>`).join('')}</tbody></table></div><button class="btn" onclick="registerImport()">Registrar resultados na bateria</button></div>`:''}</div>`}
function registerImport(){let battery=$('#importBattery')?.value;if(!battery)return alert('Selecione a bateria de destino antes de registrar.');let valid=imported.filter(x=>Number(x.kart)>0&&String(x.pilot||'').trim()&&Number.isFinite(Number(x.best))&&Number(x.best)>10&&Number(x.best)<300);if(valid.length!==imported.length&&!confirm(`${imported.length-valid.length} linha(s) inválida(s) serão ignoradas. Continuar com ${valid.length} resultado(s)?`))return;if(!valid.length)return alert('Não há resultados válidos para registrar.');if(!confirm(`Confirma registrar ${valid.length} piloto(s) na bateria selecionada?`))return;valid.forEach(x=>db.records.push({id:Date.now()+Math.random(),battery,kart:Number(x.kart),pilot:String(x.pilot).trim(),best:Number(x.best)}));imported=valid.map(x=>({...x,registered:true}));save();if(typeof syncCloud==='function')syncCloud();alert(`${valid.length} resultados registrados.`);render()}
/* V5.7 — remove Baterias e Registros apenas da tabela do dashboard, inclusive exportação/print. */
